(() => {
const screens = [
 ['01','Karşılama','TANIŞMA'],['02','Hitap','TANIŞMA'],['03','Giriş yöntemi','TANIŞMA'],
 ['04','Keşif','BİRLİKTE KEŞFET'],['05','Ana sayfa','BİRLİKTE KEŞFET'],['06','Sestia ile sohbet','BİRLİKTE KEŞFET'],['07','Oda veya eşya seçimi','BİRLİKTE KEŞFET'],
 ['08','Odalarım','YAŞAM ALANLARIN'],['09','Oda detayı','YAŞAM ALANLARIN'],['10','Eşya fotoğrafı','YAŞAM ALANLARIN'],['11','Oda fotoğrafları','YAŞAM ALANLARIN'],
 ['12','Eşya değerlendirmesi','BİRLİKTE KARAR VER'],['13','Oda değerlendirmesi','BİRLİKTE KARAR VER'],['14','Geçmiş analiz','BİRLİKTE KARAR VER'],['15','Haftalık ilham','BİRLİKTE KARAR VER'],['16','Karar kaydedildi','BİRLİKTE KARAR VER'],
 ['17','Davet kodu','DESTEK VE YÖNETİM'],['18','Geri bildirim','DESTEK VE YÖNETİM'],['19','Hata ve yeniden deneme','DESTEK VE YÖNETİM'],['20','Yönetici girişi','DESTEK VE YÖNETİM'],['21','Yönetici paneli','DESTEK VE YÖNETİM'],
 ['22','E-posta yolda','TAMAMLAYICI DURUMLAR'],['23','Hesap','TAMAMLAYICI DURUMLAR'],['24','Henüz oda yok','TAMAMLAYICI DURUMLAR'],['25','Fotoğrafa bakılıyor','TAMAMLAYICI DURUMLAR'],['26','E-posta hazır değil','TAMAMLAYICI DURUMLAR'],['27','Odaya kaydet','TAMAMLAYICI DURUMLAR']
];
const app=document.getElementById('app');
const state={name:'Deniz',email:'',decision:'',note:'',room:'Salon',roomPhotos:new Map(),singlePhoto:null,photoError:'',photoBusy:false,rooms:['Salon','Çalışma odası'],messages:[],feedback:'',excluded:false,roomDecision:'',wide:false};
function roomPhotos(room=state.room){if(!state.roomPhotos.has(room))state.roomPhotos.set(room,[]);return state.roomPhotos.get(room);}
let current='01', history=[];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,to,secondary=false)=>`<button class="${secondary?'secondary':'primary'}" data-go="${to}"><span>${label}</span><span class="arrow" aria-hidden="true">→</span></button>`;
const link=(label,to)=>`<button class="text-link" data-go="${to}">${label}</button>`;
const brand=(hero=false)=>`<img class="brand ${hero?'hero':''}" src="../marka/logo-ana-duz.webp" alt="SESTIA — Yaşam alanında, hep yanında.">`;
const heading=(title,subtitle='',center=false)=>`<div class="heading ${center?'center':''}"><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>`;
const top=(label='',back=true)=>`<div class="topbar">${back?'<button class="icon-btn back" data-back aria-label="Geri">←</button>':`<span class="mini-brand">SESTIA</span>`}${label?`<span class="mini-brand">${label}</span>`:''}${!back?'<button class="icon-btn" data-go="23" aria-label="Hesabım">○</button>':'<span style="width:44px"></span>'}</div>`;
const field=(label,name,placeholder,type='text',value='')=>`<label class="field">${label}<input name="${name}" type="${type}" placeholder="${placeholder}" value="${esc(value)}" ${type==='email'?'autocomplete="email"':'autocomplete="off"'} required maxlength="100"></label>`;
const uploadedPhoto=(item,cls='')=>`<div class="photo uploaded ${cls}"><img src="${esc(item.url)}" alt="${esc(item.name)}"></div>`;
const photo=(chair=false,cls='')=>{
 const actual=chair&&['10','12','16','25','27'].includes(current)?state.singlePhoto:!chair&&['09','13'].includes(current)?roomPhotos()[0]:null;
 return actual?uploadedPhoto(actual,cls):`<div class="photo ${chair?'chair':''} ${cls}"><img src="../sestia-ui-konseptleri-v1/${chair?'09-esya-degerlendirme':'06-oda-detay'}.png" alt="${chair?'Ahşap kollu, krem döşemeli koltuk':'Gün ışığı alan, krem kanepeli salon'}"></div>`;
};
const photoButton=(label,target,camera=false,secondary=false)=>`<button class="${secondary?'secondary':'primary'}" data-pick="${target}" ${camera?'data-camera':''} ${state.photoBusy?'disabled':''}>${label}</button>`;
const photoNotice=()=>`${state.photoBusy?'<p role="status" class="hint">Fotoğraf açılıyor…</p>':''}${state.photoError?`<p class="error" role="alert">${esc(state.photoError)}</p>`:''}`;
async function pickPhotos(target,camera){
 if(state.photoBusy)return;
 const room=state.room;
 if(target==='room'&&roomPhotos(room).length>=6)return;
 const input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png,image/webp,image/gif';input.multiple=target==='room'&&!camera;input.hidden=true;
 if(camera)input.setAttribute('capture','environment');
 document.body.appendChild(input);
 input.addEventListener('cancel',()=>input.remove(),{once:true});
 input.addEventListener('change',async()=>{
  const files=Array.from(input.files||[]);input.remove();if(!files.length)return;
  state.photoBusy=true;state.photoError='';render();const accepted=[],errors=[];
  const capacity=target==='room'?6-roomPhotos(room).length:1;
  for(const file of files){
   if(accepted.length>=capacity){errors.push('Bir odaya en fazla 6 fotoğraf ekleyebilirsin.');break;}
   if(!/^image\/(jpeg|png|webp|gif)$/.test(file.type)){errors.push('JPG, PNG, WebP veya GIF biçiminde bir fotoğraf seç.');continue;}
   if(file.size>20*1024*1024){errors.push('Her fotoğraf en fazla 20 MB olabilir.');continue;}
   const url=URL.createObjectURL(file);
   try{await new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=reject;img.src=url;});accepted.push({url,name:file.name});}
   catch{URL.revokeObjectURL(url);errors.push('Fotoğraf açılamadı. Başka bir dosya seç.');}
  }
  if(target==='room')roomPhotos(room).push(...accepted);
  else if(accepted.length){if(state.singlePhoto)URL.revokeObjectURL(state.singlePhoto.url);state.singlePhoto=accepted[0];state.decision='';state.note='';}
  state.photoError=[...new Set(errors)].join(' ');state.photoBusy=false;render();
 },{once:true});
 input.click();
}
const photoCard=(title,sub,to,chair=false)=>`<button class="photo-card" data-go="${to}" ${to==='09'?`data-room="${esc(title)}"`:''}>${to==='09'&&roomPhotos(title)[0]?uploadedPhoto(roomPhotos(title)[0]):photo(chair)}<div class="caption"><h3>${esc(title)}</h3><p>${sub}</p></div></button>`;
const section=(title,more,to)=>`<div class="section-title"><h2>${title}</h2>${more?`<button data-go="${to}">${more} →</button>`:''}</div>`;
const nav=active=>`<nav class="nav" aria-label="Uygulama gezinmesi">${[['05','⌂','Ana sayfa'],['04','✧','Keşif'],['08','▤','Odalarım'],['06','○','Sestia']].map(([id,ic,label])=>`<button data-go="${id}" class="${id===active?'active':''}"><span aria-hidden="true">${ic}</span>${label}</button>`).join('')}</nav>`;
const composer=(placeholder='Aklındakini paylaş…')=>`<form class="composer" data-form="chat"><input name="message" placeholder="${placeholder}" aria-label="Sestia'ya mesajın" required maxlength="500"><button aria-label="Mesajı gönder">↑</button></form>`;
const choices=(room=false)=>`<div class="choice-grid">${[['Tut','✓'],['Sat','◇'],['Bağışla','♡'],['Geri dönüştür','↻'],['At','×']].map(([label,icon])=>`<button class="choice ${(room?state.roomDecision:state.decision)===label?'active':''}" data-choice="${label}" ${room?'data-room-choice':''} aria-pressed="${(room?state.roomDecision:state.decision)===label}"><span class="choice-icon" aria-hidden="true">${icon}</span>${label}${label==='Tut'?'<span class="suggestion">Öneri</span>':''}</button>`).join('')}</div>`;
function roomRow(title,desc,to,chair=false){return `<button class="row card" data-go="${to}">${photo(chair,'small')}<div><h3>${title}</h3><p>${desc}</p></div><span class="chevron" aria-hidden="true">›</span></button>`;}
function shell(content,cls=''){return `<section class="screen ${cls}"><div class="status"><span>9:41</span><span aria-hidden="true">▂▄▆ &nbsp; ▰</span></div>${content}</section>`;}
function emailForm(){return `<form class="card form" data-form="email"><h2>E-posta ile devam et</h2><p class="hint">İlerlemeni hesabınla koru.</p>${field('E-posta adresin','email','ornek@email.com','email',state.email)}<button class="primary">Giriş bağlantısı gönder <span class="arrow">→</span></button></form>`;}
function home(){return `${top('',false)}${heading(`Merhaba, ${esc(state.name||'sen')}.`,'Bugün yaşam alanında neye bakalım?')}${composer()}<section>${section('Odalarım','Tümünü gör','08')}<div class="two-col">${state.rooms.slice(0,2).map(r=>photoCard(r,'Birlikte baktığımız alan','09')).join('')}</div></section><section>${section('Biraz ilham','Keşfet','15')}${photoCard('Bir köşenin başka bir hayatı','Işığa ve elindekilere yeniden bak.','15')}</section><div class="actions">${btn('Fotoğrafla birlikte bakalım','07')}</div>${nav('05')}`;}
function render(){
 const name=esc(state.name||'sen'),room=esc(state.room);let content='',cls='';
 switch(current){
 case '01': cls='welcome atmosphere';content=`${brand(true)}${heading('Etrafına bir bak.','Evinde, ofisinde, “yaşam alanım” dediğin her yerde, birlikte yeni olasılıklar keşfedebiliriz.',true)}<p class="center intro-copy">Düzenlemeden yerleşime,<br>dekorasyondan organizasyona…<br>Seninle birlikte düşünmek,<br>denemek ve yaratmak için buradayım.</p><div class="actions">${btn('Hadi Başlayalım','02')}</div><div class="signature">Bir oda. Bir eşya. Sonsuz fikir.</div>`;break;
 case '02': cls='atmosphere onboarding';content=`${top()}${brand()}${heading('Sana nasıl hitap<br>etmemi istersin?','Böylece konuşmalarımız daha sana özel olabilir.',true)}<form class="form" data-form="name">${field('Sana nasıl hitap edelim?','name','Adın ya da tercih ettiğin hitap','text',state.name==='Deniz'?'':state.name)}<button class="primary">Devam Et <span class="arrow">→</span></button></form><div class="center">${link('Şimdilik isimsiz devam et','03')}</div>`;break;
 case '03': cls='atmosphere onboarding';content=`${top()}${brand()}${heading('Nasıl devam etmek<br>istersin?',state.name?`Memnun oldum, ${name}.`:'İstersen hesabınla ilerleyebilir, istersen misafir olarak devam edebilirsin.',true)}${emailForm()}<div class="divider">veya</div>${btn('Misafir olarak devam et','04',true)}`;break;
 case '04': content=`${top('',false)}<div class="eyebrow">Bir oda. Bir eşya. Sonsuz fikir.</div>${heading('Birlikte bakalım.','Bir fikirle, bir soruyla ya da sadece merakla başlayabiliriz.')}<div class="card"><h2>Aklına takılan bir şey var mı?</h2><p>Sestia burada. Nereden başlamak istersin?</p><div style="margin-top:16px">${composer("Sestia'ya yaz…")}</div></div>${photoCard('Bir köşenin başka bir hayatı','Birlikte düşünelim →','06')}<div class="actions">${btn('Bir fotoğrafla başlayalım','07')}</div>${nav('04')}`;break;
 case '05':content=home();break;
 case '06':cls='chat';content=`${top('Sestia')}<div class="eyebrow">Birlikte bakalım</div><div class="conversation"><div class="bubble user">Pencere önünü okuma köşesi yapmak istiyorum.</div><div class="bubble"><div class="eyebrow">Sestia</div>Koltuğu ışığı yandan alacak şekilde çevirebiliriz. Yanına küçük bir sehpa, akşam için de bir okuma lambası düşünülebilir.</div>${photo(true)}<small>Bir yerleşim fikri</small>${state.messages.map(m=>`<div class="bubble user">${esc(m)}</div><div class="bubble"><div class="eyebrow">Sestia · Örnek yanıt</div>Önce bu köşede ne yapmak istediğinden başlayabiliriz. Elindekilerle bir yerleşim denemeye ne dersin?</div>`).join('')}</div>${composer('Aklındakini yaz…')}`;break;
 case '07':content=`${top()}${heading('Bir oda veya<br>bir eşya seç.','Fotoğrafını çek ya da galerinden yükle. Neler yapabileceğimize birlikte bakalım.')}${roomRow('Tek eşya','Bir eşyayı birlikte değerlendirelim.','10',true)}${roomRow('Oda taraması','Odanın genel hâline birlikte bakalım.','11')}<p class="hint center">Üzerine konuşmak istediğin yerden başla.</p>`;break;
 case '08':content=`${top()}${heading('Odalarım','Birlikte baktığımız alanlar.')}${state.rooms.map(r=>photoCard(r,'3 fotoğraf · 2 analiz','09')).join('')}<form class="form" data-form="room">${field('Yeni bir alan','room','Yeni oda adı')}<button class="primary">Oda ekle <span class="arrow">＋</span></button></form>${nav('08')}`;break;
 case '09':content=`${top()}${heading(room,'Bu odada görmek, anlamak, değiştirmek istediğin her şeye birlikte bakalım.')}${photo()}<div class="quick"><button class="chip" data-go="11">＋ Fotoğraf ekle</button><button class="chip" data-go="06">Sestia ile konuş</button></div><div class="actions">${btn('Odaya birlikte bakalım','13')}${btn('Bir eşyaya bakalım','10',true)}</div><section>${section('Önceki analizler')}${roomRow('Pencere önü','22 Eylül · Görüntüle','14')}</section><section>${section('Kararlarım')}${roomRow('Ahşap sandalye',`Seçimin: ${esc(state.decision||'Tut')}`,'14',true)}</section>`;break;
 case '10':content=`${top()}${heading('Birlikte bakalım.','Üzerine konuşmak istediğin eşyanın fotoğrafını paylaş.')}${state.singlePhoto?`${photo(true)}<button class="text-link" data-remove-single>Fotoğrafı kaldır</button>`:'<button class="upload" data-pick="single"><span class="large-icon" aria-hidden="true">＋</span>Fotoğrafını buraya ekle</button>'}${photoNotice()}<div class="actions">${photoButton(state.singlePhoto?'Yeni fotoğraf çek':'Fotoğraf çek','single',true)}${photoButton('Galeriden seç','single',false,true)}${state.singlePhoto?btn('Bu fotoğrafla devam et','25'):''}</div><p class="hint center">Eşyanın tamamı ve ayrıntıları görünsün. JPG, PNG, WebP veya GIF · En fazla 20 MB.</p>`;break;
 case '11':content=`${top()}${heading('Alanı birlikte görelim.',room)}<div class="thumbs">${roomPhotos().map((item,i)=>`<div class="thumb">${uploadedPhoto(item)}<button class="icon-btn" data-remove="${i}" aria-label="${i+1}. fotoğrafı kaldır">×</button></div>`).join('')}${roomPhotos().length<6?'<button class="upload" data-pick="room">＋ Fotoğraf ekle</button>':''}</div>${photoNotice()}<p class="hint">Farklı açılar, alanı daha iyi anlamamıza yardımcı olur.</p><div class="quick"><button class="chip" data-pick="room" data-camera ${roomPhotos().length>=6||state.photoBusy?'disabled':''}>Kamera</button><button class="chip" data-pick="room" ${roomPhotos().length>=6||state.photoBusy?'disabled':''}>Galeri</button></div><div class="actions bottom"><button class="primary" data-go="13" ${!roomPhotos().length||state.photoBusy?'disabled':''}>Bu fotoğraflarla devam et <span class="arrow">→</span></button><small class="center">${roomPhotos().length} / 6 fotoğraf</small></div>`;break;
 case '12':content=`${top()}${photo(true)}<small>${room} · Ahşap sandalye</small>${heading('Birlikte değerlendirelim.','Ahşap gövde ve açık renk döşeme, farklı köşelere uyum sağlayabilir.')}<div class="card"><h2>Sen ne düşünüyorsun?</h2>${choices()}<p>Öneri bir başlangıç. Son karar senin.</p></div><label class="field">Eklemek istediğin bir şey var mı?<textarea id="decision-note" placeholder="Notunu buraya yazabilirsin…">${esc(state.note)}</textarea></label><div class="actions"><button class="primary" data-go="27" ${!state.decision?'disabled':''}>Kararımı kaydet <span class="arrow">→</span></button></div>`;break;
 case '13':content=`${top()}${heading(`${room} için birlikte bakalım.`)}${photo()}<div class="card"><div class="eyebrow">Sestia</div><p>Pencere önü, farklı bir yerleşimi denemek için iyi bir başlangıç olabilir.</p></div><section>${section('Eşyalar üzerine')}<p class="hint">Öneriyi değerlendir; kaydetmek için kendi seçimini yap.</p></section><div class="card">${photo(true,'small')}<h2 style="margin-top:14px">Ahşap sandalye</h2>${state.excluded?'<p>Bu değerlendirmeye dahil edilmeyecek.</p>':choices(true)}<button class="text-link" data-exclude>${state.excluded?'Tekrar dahil et':'Hariç tut'}</button></div>${composer('Oda hakkında konuşalım…')}<button class="primary" data-confirm-room ${!state.roomDecision&&!state.excluded?'disabled':''}>Seçimlerimi onayla <span class="arrow">→</span></button>`;break;
 case '14':content=`${top()}<div class="eyebrow">Geçmiş analiz</div>${heading('Birlikte baktıklarımız',`${room} · 22 Eylül 2026`)}${photo()}<div class="card"><span class="badge">Sestia’nın önerisi</span><h2 style="margin-top:12px">Ahşap sandalye: Tut</h2></div><div class="card"><span class="badge chosen">Senin seçimin</span><h2 style="margin-top:12px">Ahşap sandalye: ${esc(state.decision||'Tut')}</h2></div><div class="card"><h2>Notun</h2><p>“${esc(state.note||'Bu sandalye benim için hatıra.')}”</p></div><div class="actions bottom">${btn('Odaya dön','09')}</div>`;break;
 case '15':content=`${top()}${heading('Bu haftanın fikirleri','Yaşam alanına küçük dokunuşlar.')}${photo()}${roomRow('Işığa yer aç','Pencere önündeki küçük eşyaları bir araya getir.','06')}${roomRow('Bir arada, daha kolay','Sık kullandıklarını erişebileceğin yerde tut.','06',true)}<div class="signature">Elindekilere yeniden bak.</div>${link('Sestia ile birlikte düşün','06')}`;break;
 case '16':cls='success atmosphere';content=`<div class="success-icon" aria-hidden="true">✓</div>${heading('Kararın kaydedildi.',`Ahşap sandalye için seçimin: ${esc(state.decision||'Tut')}.`,true)}${photo(true)}<div class="actions">${btn('Odama dön','09')}${link('Başka bir eşyaya bak','10')}</div>`;break;
 case '17':cls='atmosphere onboarding';content=`${brand(true)}${heading('Hoş geldin.','Sestia’nın erken erişim deneyimine davetlisin.',true)}<form class="form" data-form="invite">${field('Davet kodun','code','Kodunu yaz')}<button class="primary">Devam et <span class="arrow">→</span></button></form><small class="center">Birlikte yeni olasılıklar keşfedelim.</small>`;break;
 case '18':content=`${home()}<div class="sheet-backdrop"><form class="sheet" data-form="feedback" aria-label="Geri bildirim"><button type="button" class="icon-btn close" data-go="05" aria-label="Kapat">×</button><h1>Geri bildirim</h1><p>Bir fikrin ya da paylaşmak istediğin bir şey var mı?</p><label class="field">Mesajın<textarea name="feedback" placeholder="Aklındakini yaz…" required maxlength="2000">${esc(state.feedback)}</textarea></label><button class="primary">Gönder <span class="arrow">→</span></button></form></div>`;break;
 case '19':cls='atmosphere';content=`${top()}<div class="success-icon" aria-hidden="true">!</div>${heading('Bir şeyler<br>yolunda gitmedi.','Birazdan yeniden deneyebilirsin.',true)}<div class="actions">${btn('Tekrar dene','25')}${link('Ana sayfaya dön','05')}</div>`;break;
 case '20':cls='atmosphere onboarding';content=`${top('SESTIA')}${brand()}${heading('Sahibi Paneli','Yönetici erişim kodunu gir.',true)}<form class="form" data-form="admin">${field('Yönetici kodu','code','Yönetici kodu','password')}<button class="primary">Giriş yap <span class="arrow">→</span></button></form>`;break;
 case '21':content=`${top('Sahibi Paneli')}${heading('Sahibi Paneli','Örnek veriler · 19–25 Eylül 2026')}<div class="admin-grid"><div class="card"><div class="eyebrow">Aktif cihaz</div><div class="metric">24</div><small>Son 7 gün</small></div><div class="card"><h2>Günlük karar sayısı</h2><div class="chart" role="img" aria-label="19–25 Eylül karar sayıları: 3, 5, 4, 8, 6, 11, 9">${[3,5,4,8,6,11,9].map((n,i)=>`<div class="bar">${n}<i style="height:${n*9}px"></i>${19+i} Eyl</div>`).join('')}</div></div></div><div class="card"><h2>Geri bildirimler</h2><div class="table-wrap"><table><thead><tr><th>Tarih</th><th>Kullanıcı</th><th>Mesaj</th></tr></thead><tbody><tr><td>25 Eyl</td><td>Deniz</td><td>Odamın fotoğraflarına dönmek çok kolay.</td></tr><tr><td>24 Eyl</td><td>Ece</td><td>Fotoğraf eklerken daha fazla yönlendirme isterdim.</td></tr></tbody></table></div></div><div class="card"><h2>Hatalar</h2><div class="table-wrap"><table><thead><tr><th>Tarih</th><th>Tür</th><th>Mesaj</th></tr></thead><tbody><tr><td>25 Eyl</td><td>Fotoğraf</td><td>Yükleme tamamlanamadı.</td></tr><tr><td>24 Eyl</td><td>Bağlantı</td><td>İstek zaman aşımına uğradı.</td></tr></tbody></table></div></div>`;break;
 case '22':cls='atmosphere onboarding';content=`${top()}${brand()}${heading('E-posta yolda.','Giriş bağlantın için gelen kutuna bak.',true)}<div class="card center"><h2>${esc(state.email||'deniz@ornek.com')}</h2><p>Bu adrese gönderilen bağlantıyla devam edebilirsin. Gelen kutunda yoksa gereksiz klasörüne de bak.</p></div><div class="actions">${btn('E-posta adresini değiştir','03',true)}${link('Misafir olarak devam et','04')}</div>`;break;
 case '23':content=`${top()}${heading('Hesabın',`Merhaba, ${name}.`)}<div class="card"><span class="badge">Misafir oturumu</span><h2 style="margin-top:15px">Birlikte devam edelim.</h2><p>İlerlemeni hesabınla korumak için e-posta ile devam edebilirsin.</p></div>${btn('E-posta ile devam et','03')}<div class="card"><h2>Tercih ettiğin hitap</h2><p>${name}</p>${link('Hitabımı değiştir','02')}</div>${btn('Geri bildirim paylaş','18',true)}${nav('')}`;break;
 case '24':content=`${top()}${heading('Odalarım','Her şey bir alanla başlar.')}<div class="empty"><div class="large-icon" aria-hidden="true">⌂</div><h2>İlk odana yer aç.</h2><p>Bir ad ver; fotoğraflarını ve birlikte baktıklarımızı burada bir araya getirelim.</p></div><form class="form" data-form="room">${field('Oda adı','room','Örneğin: Salon')}<button class="primary">İlk odamı ekle <span class="arrow">＋</span></button></form>${nav('08')}`;break;
 case '25':content=`${top()}${photo(true)}${heading('Fotoğrafına<br>birlikte bakalım.','Fotoğrafın hazır. Bu prototipte değerlendirme örneğini inceleyebilirsin.')}<div class="card loading-lines" role="status" aria-label="Fotoğraf değerlendiriliyor"><span></span><span></span><span></span></div><div class="actions bottom">${btn('Örnek değerlendirmeyi gör','12')}${link('Fotoğrafı değiştir','10')}</div>`;break;
 case '26':cls='atmosphere onboarding';content=`${top()}${brand()}${heading('Birlikte başlayabiliriz.','E-posta ile giriş şu anda hazır değil.',true)}<div class="card"><h2>Misafir olarak keşfet.</h2><p>Sestia ile konuşabilir, fotoğraflarına birlikte bakabilirsin.</p></div>${btn('Misafir olarak devam et','04')}${link('Tekrar dene','03')}`;break;
 case '27':content=`${top()}${heading('Hangi odada kalsın?','Kararını bir odayla ilişkilendir.')}<div class="card row">${photo(true,'small')}<div><h3>Ahşap sandalye</h3><span class="badge chosen">${esc(state.decision||'Tut')}</span></div></div><form class="form" data-form="save"><label class="field">Odan<select name="room">${state.rooms.map(r=>`<option ${r===state.room?'selected':''}>${esc(r)}</option>`).join('')}</select></label><button class="primary">Kaydet <span class="arrow">→</span></button></form>${link('Yeni oda ekle','08')}`;break;
 }
 app.innerHTML=shell(content,cls);app.className=(state.wide?'wide ':'')+(current==='21'?'admin':'');
 const spec=screens.find(s=>s[0]===current);document.getElementById('screen-label').textContent=`${spec[0]} / ${spec[1]}`;document.getElementById('group-label').textContent=spec[2];
 document.querySelectorAll('.screen-link').forEach(a=>{a.classList.toggle('active',a.dataset.id===current);if(a.dataset.id===current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 const notes={ '01':'Ana referans: paylaştığın 1. ekran. Büyük logo, sıcak ışık, serif anlatım ve doğal dekor.', '02':'Ana referans: paylaştığın 2. ekran. 2 ve 3. ekran aynı logo ölçüsünü ve form hizasını paylaşır.', '03':'Ana referans: paylaştığın 3. ekran. Hesap faydası e-posta kartında; misafir seçeneği ayrı.', '04':'Tasarım önerisi: Keşif her zaman erişilebilir. Yeni alt gezinme dört ana yüzeyi birbirine bağlar.', '10':'Fotoğrafını cihazından seçebilirsin. Kamera seçeneği destekleyen telefonlarda kamerayı açar. Fotoğraflar yalnızca bu açık sayfada tutulur; analiz örnektir.', '11':'Bir odaya en fazla 6 fotoğraf seçebilir ve kaldırabilirsin. Fotoğraflar cihazından dışarı gönderilmez; sayfa yenilenince sıfırlanır.', '12':'Karamel etiket Sestia’nın önerisi, petrol yeşili senin seçimin. Bir seçim yapmadan kaydetme etkinleşmez.', '13':'Öneriler kendiliğinden kaydedilmez. Seçim veya hariç tutma gerekir.', '18':'Gönderme yalnızca prototip içinde canlandırılır; gerçek geri bildirim gönderilmez.', '21':'Yönetim ekranındaki bütün veriler örnektir.', '22':'E-posta gönderimi prototipte canlandırılır; gerçek e-posta gönderilmez.', '25':'Yükleniyor durumu sabittir; örnek sonucu görmek için düğmeyi kullan.'};
 document.getElementById('design-note').textContent=notes[current]||'Paylaştığın üç ekranın devamı: ortak tipografi, petrol yeşili eylemler, krem yüzeyler. Etkileşimler örnek verilerle çalışır.';
}
function go(id,push=true){if(!screens.some(s=>s[0]===id))id='01';if(push&&id!==current)history.push(current);current=id;window.location.hash=id;render();if(push)document.querySelector('.toolbar').scrollIntoView({block:'start'});}
let lastGroup='';document.getElementById('screen-list').innerHTML=screens.map(([id,title,group])=>{const prefix=group!==lastGroup?`<div class="group">${group}</div>`:'';lastGroup=group;return prefix+`<a class="screen-link" href="#${id}" data-id="${id}"><span>${id}</span>${title}</a>`;}).join('');
app.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-back')){go(history.pop()||'05',false);return;}
 if(b.dataset.room)state.room=b.dataset.room;
 if(b.dataset.go){if(current==='02'&&b.dataset.go==='03')state.name='';go(b.dataset.go);return;}
 if(b.dataset.choice){if(b.hasAttribute('data-room-choice'))state.roomDecision=b.dataset.choice;else state.decision=b.dataset.choice;render();return;}
 if(b.dataset.pick){pickPhotos(b.dataset.pick,b.hasAttribute('data-camera'));return;}
 if(b.hasAttribute('data-remove')){const removed=roomPhotos().splice(Number(b.dataset.remove),1)[0];if(removed)URL.revokeObjectURL(removed.url);state.photoError='';render();}
 if(b.hasAttribute('data-remove-single')){if(state.singlePhoto)URL.revokeObjectURL(state.singlePhoto.url);state.singlePhoto=null;state.photoError='';state.decision='';render();}
 if(b.hasAttribute('data-exclude')){state.excluded=!state.excluded;render();}
 if(b.hasAttribute('data-confirm-room')){if(state.excluded){go('09');}else{state.decision=state.roomDecision;go('16');}}
});
app.addEventListener('input',e=>{if(e.target.id==='decision-note')state.note=e.target.value;});
app.addEventListener('submit',e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();const data=new FormData(f);switch(f.dataset.form){
 case 'name':state.name=data.get('name').trim();if(state.name)go('03');break;
 case 'email':state.email=data.get('email').trim();go('22');break;
 case 'invite':go('02');break;
 case 'admin':go('21');break;
 case 'room':{const value=data.get('room').trim();if(!value)return;if(!state.rooms.includes(value))state.rooms.push(value);state.room=value;go('09');break;}
 case 'chat':{const value=data.get('message').trim();if(value){state.messages.push(value);go('06');}break;}
 case 'save':state.room=data.get('room');go('16');break;
 case 'feedback':state.feedback=data.get('feedback').trim();if(!state.feedback)return;f.innerHTML='<div class="success-icon">✓</div><h1>Teşekkürler.</h1><p>Geri bildirimin alındı.</p><small>Bu bir prototip gösterimidir; gerçek mesaj gönderilmedi.</small>'+btn('Ana sayfaya dön','05');break;
}});
document.getElementById('previous').onclick=()=>go(screens[(screens.findIndex(s=>s[0]===current)+screens.length-1)%screens.length][0]);
document.getElementById('next').onclick=()=>go(screens[(screens.findIndex(s=>s[0]===current)+1)%screens.length][0]);
document.getElementById('wide').onclick=e=>{state.wide=!state.wide;e.currentTarget.setAttribute('aria-pressed',state.wide);e.currentTarget.textContent=state.wide?'Mobil görünüm':'Geniş görünüm';render();};
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(id!==current)go(id);});
go(location.hash.slice(1)||'01',false);
})();
